#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;
using static VfxKit.VfxLightningKit;

namespace VfxEffects
{
    // Generated by vfx-shader. Rebuilt from this script: edit here, not in the Inspector.
    // Lightning aura around a weapon / gauntlet (loop), set up like the rpg-game VFX_Aura_Gauntlet_Prismatic (read + rendered, numbers in
    // .claude/skills/vfx-shader/references/lightning-set.md). Four layers: red smoke rising off the object (root), a low smoke haze,
    // mesh lightning bolts around it (Guardian_Lighting, Lightning_CustomBlend with the purple-cyan Guardian_Gradient and a magenta HDR tint) and
    // soft light dots drifting out. The reference smoke uses an URP-only ShaderGraph: replaced by the default smoke (art lead 2026-11-03:
    // fx_t_smoke_02 + Mobile/Particles/Alpha Blended, tinted by Start Color). No transform has a scale; every layer is Hierarchy.
    // The reference emits from a staff mesh that is not in the project: a 1.5 m tall box / ellipsoid around the origin stands in for it.
    // Space (proposal): loop, aura around a 1.5 m object standing at the origin, 3/4 camera, 2 m scale.
    public static class AuraGauntletBuild
    {
        const string Root = "Assets/VFX/AuraGauntlet";
        const string Lib = "Assets/VFX/_Imported/RpgGame/Lightning/";   // meshes only
        // textures come from Assets/Library (art lead rule 2026-11-04), loaded as they are (shared files: no import changes)
        const string TexBolt = "Assets/Library/Lightnings_Electrics/Lightnings_Electrics_007.png";   // = rpg-game Guardian_Lightning3 (wavy bolt, 512x256)
        const string TexDot = "Assets/Library/glow/glow_012.png";                                    // soft round dot (closest to rpg-game Rectangle 1)
        const long AuraMeshLocalId = 4864056309639282896L;   // sub-mesh of Guardian_Lighting.fbx used by the reference
        static readonly Vector3 Centre = new Vector3(0f, 0.75f, 0f);

        [MenuItem("VFX/AuraGauntlet/Build")]
        public static void Build()
        {
            if (!ConfirmSceneSwitch()) return;
            EnsureFolders(Root, "Materials", "Prefabs", "Scenes", "Textures");
            string M(string part) => Root + "/Materials/M_AuraGauntlet_" + part + ".mat";
            var smokeTex = ImportTexture("Assets/VFX/fx_t_smoke_02.png", 512);
            var mSmoke = Material(M("Smoke"), VfxBlend.Alpha, smokeTex);
            var mDot = Material(M("Dot"), VfxBlend.Additive, AssetDatabase.LoadAssetAtPath<Texture2D>(TexDot));
            var main = AssetDatabase.LoadAssetAtPath<Texture2D>(TexBolt);
            var gradient = Ramp(Root + "/Textures/T_AuraGauntlet_Ramp.png");
            var mBolt = LightningMaterial(M("Bolt"), main, gradient, new Color(11.57f, 0.545f, 0.928f, 1f), 2f, -0.07f, 0.4f, 3f, 1f);
            ResetTiling(mSmoke, mDot, mBolt);
            var mesh = FindAuraMesh(Lib + "Mesh/Guardian_Lighting.fbx");

            // ---- root: red smoke rising off the object (reference: rate 12, life 1-2.5, speed 0-0.5, size 0.5-1, gravity -0.1, max 50, red two colours)
            var root = new GameObject("VFX_AuraGauntlet");
            var smoke = ParticleOn(root, mSmoke, lifetime: 2.5f, size: 1f, color: Color.white);
            Loop(smoke, 2f);
            SmokeLayer(smoke, 1f, 2.5f, 0.5f, 1f, 12f, 0.61f);
            TwoColors(smoke, new Color(1f, 0f, 0.16f), new Color(1f, 0.27f, 0.36f));
            Box(smoke, Centre, new Vector3(0.3f, 1.5f, 0.3f));
            smoke.GetComponent<ParticleSystemRenderer>().sortingOrder = 0;

            // ---- smoke: low haze (reference: rate 11, size 1-2, colour (1, 0.83, 0.85), order 2, near the ground)
            var haze = Particle(root.transform, "smoke", mSmoke, lifetime: 2.5f, size: 1f, color: new Color(1f, 0.83f, 0.85f, 1f));   // reference colour; tinted red below because the default smoke is alpha blended (the reference shader is additive-like)
            Loop(haze, 2f);
            SmokeLayer(haze, 1f, 2.5f, 0.8f, 1.5f, 11f, 0.61f);
            TwoColors(haze, new Color(1f, 0.25f, 0.4f, 0.55f), new Color(0.9f, 0.1f, 0.3f, 0.45f));
            Box(haze, new Vector3(0f, 0.17f, 0f), new Vector3(0.7f, 0.3f, 0.7f));
            haze.GetComponent<ParticleSystemRenderer>().sortingOrder = 2;

            // ---- electric: mesh bolts around the object (reference: rate 10, life 0.4-0.7, 3D size X 0.3-0.6 Y 1 Z 0.5, sim speed 0.75, cutoff curve -0.31 -> 1)
            var bolt = Particle(root.transform, "electric", mBolt, lifetime: 0.7f, size: 1f, color: Color.white);
            Loop(bolt, 2f);
            var bm = bolt.main; bm.maxParticles = 1000; bm.simulationSpeed = 0.75f;
            Range(bolt, 0.4f, 0.7f, 0f, 0f);
            Size3D(bolt, new Vector2(0.3f, 0.6f), new Vector2(1f, 1f), new Vector2(0.5f, 0.5f));
            bm.startRotation = new ParticleSystem.MinMaxCurve(0f, 6.28318f);
            var be = bolt.emission; be.rateOverTime = 10f; be.SetBursts(new ParticleSystem.Burst[0]);
            var bs = bolt.shape;
            bs.enabled = true; bs.shapeType = ParticleSystemShapeType.Sphere; bs.radius = 0.5f; bs.radiusThickness = 0f;
            bs.scale = new Vector3(1.5f, 1.5f, 1f); bs.position = Centre; bs.alignToDirection = true; bs.randomDirectionAmount = 1f;
            SizeOverLifetime(bolt, 0f, 0.71f, 0.05f, 1f, 1f, 1f);
            LightningCustomData(bolt, 0f, -0.31f, 0.15f, 0.56f, 0.31f, 0.64f, 0.45f, 0.84f, 1f, 1f);
            var br = bolt.GetComponent<ParticleSystemRenderer>();
            br.renderMode = ParticleSystemRenderMode.Mesh; br.mesh = mesh; br.alignment = ParticleSystemRenderSpace.Local; br.sortingOrder = 2; br.maxParticleSize = 0.5f;
            LightningStreams(bolt);

            // ---- dot_Light: soft dots drifting out (reference: rate 7, life 0.5-1, speed 1-2, size 1, noise strength 1 freq 2, order 3)
            var dot = Particle(root.transform, "dot_Light", mDot, lifetime: 1f, size: 1f, color: new Color(0.99f, 0.88f, 0.89f, 1f));
            Loop(dot, 2f);
            var dm = dot.main; dm.maxParticles = 1000; dm.startSize = 0.35f;   // 0.35 m dots (reference size 1 in a differently scaled prefab)
            Range(dot, 0.5f, 1f, 1f, 2f);
            var de = dot.emission; de.rateOverTime = 7f; de.SetBursts(new ParticleSystem.Burst[0]);
            var ds = dot.shape;
            ds.enabled = true; ds.shapeType = ParticleSystemShapeType.Sphere; ds.radius = 0.5f; ds.radiusThickness = 1f; ds.scale = new Vector3(1.4f, 1.6f, 1.4f); ds.position = Centre;
            SizeOverLifetime(dot, 0f, 1f, 1f, 0f);
            AlphaOverLifetime(dot, 0f, 1f, 1f, 0f);
            var dn = dot.noise; dn.enabled = true; dn.strength = 1f; dn.frequency = 2f; dn.damping = true; dn.octaveCount = 1; dn.sizeAmount = 1f;
            dot.GetComponent<ParticleSystemRenderer>().sortingOrder = 3;

            var prefab = SavePrefab(root, Root + "/Prefabs/VFX_AuraGauntlet.prefab");
            var look = new Vector3(0f, 1f, 0f);
            const float d = 5.5f;
            var cam = look + new Vector3(0f, Mathf.Sin(40f * Mathf.Deg2Rad) * d, -Mathf.Cos(40f * Mathf.Deg2Rad) * d);
            Finish(prefab, Root, "AuraGauntlet", new[] { 0.3f, 0.7f, 1.2f, 1.8f, 2.5f, 3.2f, 4f, 5f }, cam, look);
        }

        public static void BuildBatch() => RunBatch(Build);

        // colour ramp of the bolt shader (dark purple -> blue -> cyan -> white, like rpg-game's Guardian_Gradient): the Library has no such ramp, so it is generated
        static Texture2D Ramp(string path)
        {
            if (!System.IO.File.Exists(path))
            {
                var tex = new Texture2D(64, 4, TextureFormat.RGBA32, false);
                var g = new Gradient();
                g.SetKeys(new[] { new GradientColorKey(new Color(0.22f, 0.02f, 0.30f), 0f), new GradientColorKey(new Color(0.18f, 0.16f, 0.52f), 0.4f), new GradientColorKey(new Color(0.05f, 0.62f, 0.72f), 0.8f), new GradientColorKey(Color.white, 1f) },
                           new[] { new GradientAlphaKey(1f, 0f), new GradientAlphaKey(1f, 1f) });
                for (int x = 0; x < 64; x++) for (int y = 0; y < 4; y++) tex.SetPixel(x, y, g.Evaluate(x / 63f));
                tex.Apply();
                System.IO.File.WriteAllBytes(path, tex.EncodeToPNG());
                Object.DestroyImmediate(tex);
                AssetDatabase.ImportAsset(path);
            }
            return ImportTexture(path, 64, clamp: true);
        }

        static void SmokeLayer(ParticleSystem ps, float lifeMin, float lifeMax, float sizeMin, float sizeMax, float rate, float sizeStart)
        {
            var m = ps.main;
            m.maxParticles = 50; m.gravityModifier = -0.1f;
            m.startRotation = new ParticleSystem.MinMaxCurve(0f, 6.28318f);
            m.startSize = new ParticleSystem.MinMaxCurve(sizeMin, sizeMax);
            Range(ps, lifeMin, lifeMax, 0f, 0.5f);
            var e = ps.emission; e.rateOverTime = rate; e.SetBursts(new ParticleSystem.Burst[0]);
            SizeOverLifetime(ps, 0f, sizeStart, 1f, 0f);
            AlphaOverLifetime(ps, 0f, 0f, 0.48f, 1f, 1f, 0f);
        }

        static void Box(ParticleSystem ps, Vector3 pos, Vector3 size)
        {
            var sh = ps.shape;
            sh.enabled = true; sh.shapeType = ParticleSystemShapeType.Box; sh.position = pos; sh.scale = size; sh.rotation = Vector3.zero;
        }

        static Mesh FindAuraMesh(string path)
        {
            Mesh first = null;
            foreach (var o in AssetDatabase.LoadAllAssetsAtPath(path))
            {
                var m = o as Mesh;
                if (m == null) continue;
                first = first ?? m;
                if (AssetDatabase.TryGetGUIDAndLocalFileIdentifier(m, out _, out long id) && id == AuraMeshLocalId) return m;
            }
            return first;
        }
    }
}
#endif
